// Helper function to calculate strength of an extension
function method strength(extension: string) returns (s: int)
{
    var cap := CountUppercase(extension);
    var sm := CountLowercase(extension);
    s := cap - sm;
}

// Helper functions to count uppercase and lowercase letters
function method CountUppercase(s: string) returns (count: int)
{
    count := |{c | c in s | 'A' <= c && c <= 'Z'}|; // Count of uppercase letters
}

function method CountLowercase(s: string) returns (count: int)
{
    count := |{c | c in s | 'a' <= c && c <= 'z'}|; // Count of lowercase letters
}
